1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16		"unicode/utf8"
17	)
18	
19	// Status 表示样品所处的判定状态。
20	type Status string
21	
22	const (
23		// StatusPending 样品已录入，尚未确认判定结果。
24		StatusPending Status = "pending"
25		// StatusConfirmed 样品已确认，判定结果已保存。
26		StatusConfirmed Status = "confirmed"
27		// StatusVoided 样品已作废，保留记录但不能再确认。
28		StatusVoided Status = "voided"
29	)
30	
31	var (
32		ErrClosed             = errors.New("water: 数据存放已关闭")
33		ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
34		ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
35		ErrUnknownPoint       = errors.New("water: 采样点未登记")
36		ErrInvalidValue       = errors.New("water: 数值只接受有限数")
37		ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
38		ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
39		ErrUnknownSample      = errors.New("water: 样品编号不存在")
40		ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
41		ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
42		ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
43		ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
44		ErrVoided             = errors.New("water: 样品已作废，不能再确认")
45		ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
46		ErrInvalidText        = errors.New("water: 采样点编号、名称、项目名、样品编号或作废原因不是合法的 UTF-8 文本")
47		ErrCorruptRecord      = errors.New("water: 本地数据中存在缺少原测量、测量项目重复或测量项目与逐项判定对应不上的损坏样品记录")
48	)
49	
50	// SamplingPoint 是按编号唯一登记的采样点。
51	type SamplingPoint struct {
52		ID   string `json:"id"`
53		Name string `json:"name"`
54	}
55	
56	// Limit 是某采样点某测量项目的一版数值上限。
57	type Limit struct {
58		PointID   string    `json:"pointId"`
59		Item      string    `json:"item"`
60		Value     float64   `json:"value"`
61		Effective time.Time `json:"effective"`
62	}
63	
64	// Measurement 是样品中一个项目的测量值。
65	type Measurement struct {
66		Item  string  `json:"item"`
67		Value float64 `json:"value"`
68	}
69	
70	// ItemResult 是确认后单个项目的判定结果。
71	type ItemResult struct {
72		Item           string    `json:"item"`
73		Value          float64   `json:"value"`
74		Limit          float64   `json:"limit"`
75		LimitEffective time.Time `json:"limitEffective"`
76		Exceeded       bool      `json:"exceeded"`
77	}
78	
79	// Sample 是一份从录入、确认到作废的样品记录。
80	type Sample struct {
81		ID           string        `json:"id"`
82		PointID      string        `json:"pointId"`
83		SampledAt    time.Time     `json:"sampledAt"`
84		Measurements []Measurement `json:"measurements"`
85		Status       Status        `json:"status"`
86		Results      []ItemResult  `json:"results,omitempty"`
87		Exceeded     bool          `json:"exceeded"`
88		VoidReason   string        `json:"voidReason,omitempty"`
89	}
90	
91	// diskState 是落盘的完整数据。
92	type diskState struct {
93		Points  map[string]SamplingPoint `json:"points"`
94		Limits  map[string][]Limit       `json:"limits"` // 键仅为落盘占位，读取时按每条限值自身的采样点与项目重新分组
95		Samples map[string]*Sample       `json:"samples"`
96	}
97	
98	// limitGroup 用两个字段各自标识一组限值，避免把包含 U+0000 的文本
99	// 用单字符拼接成键时不同组合撞成同一组。
100	type limitGroup struct {
101		pointID string
102		item    string
103	}
104	
105	// Store 是绑定到某个本地目录的取样判定数据存放。
106	// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
107	type Store struct {
108		mu      sync.Mutex
109		dir     string
110		file    string
111		closed  bool
112		points  map[string]SamplingPoint
113		limits  map[limitGroup][]Limit // 按生效时间升序
114		samples map[string]*Sample
115	}
116	
117	// Open 打开（必要时创建）dir 下的本地数据存放。
118	//
119	// 读入时先核对每份样品都至少保留一个原测量项目：Measurements 为空列表、保存为
120	// null 或整个字段缺失都算样品内容残缺，即使编号、采样点、采样时间齐全也不能
121	// 接受；这条要求对任何状态的样品都生效，包括待判定样品，以及待判定后直接作废、
122	// 不再参与有效判定的样品——不能因为它没有历史结论就放过内容丢失；原测量为空但
123	// 残留逐项判定的记录也不能反过来用判定内容填补原测量。再核对原测量项目名：
124	// 同一个测量项目名在一份样品里只能出现一次，不依赖两条记录是否相邻，也不因
125	// 数值相同（包括两个零）而放行。再核对每份已保存结论的样品：已确认样品，以及
126	// 已确认后作废、逐项依据仍保留在 Results 中的样品，其原测量项目与逐项判定
127	// 必须按项目名完整一一对应；判定里同一项目不能出现两次；每个测量项目必须且
128	// 只能有一条判定，判定里也不能出现原测量没有的项目；对应项目的判定测量值必须
129	// 与原测量值一致（零是合法测量值，不会被当成缺项）。两个列表排列顺序不同不
130	// 影响对应，成功读入后测量与判定各自保留原顺序。任一份样品对不上，整次打开
131	// 以可被 errors.Is(err, ErrCorruptRecord) 识别的错误失败，返回 nil 数据存放，
132	// 错误信息点到具体样品编号与缺少原测量的原因（或具体项目）；不会静默跳过问题
133	// 样品、不会择一保留或合并重复测量、不会补出缺失测量或判定、不会把它改成另一
134	// 种状态、也不会把拒绝推迟到请求确认时，更不会改写原文件。待判定样品没有判定
135	// 记录、待判定后作废的样品没有历史依据，均属正常，只要原测量完整就照常读入。
136	// 完整记录原样读入，已保存的上限、生效时间、逐项结论与整份超标标记保留，不因
137	// 后来新增或补录的限值而拒绝或重新计算。没有任何样品的新数据目录，以及样品
138	// 集合为空的已有数据，都照常打开。
139	func Open(dir string) (*Store, error) {
140		if strings.TrimSpace(dir) == "" {
141			return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
142		}
143		if err := os.MkdirAll(dir, 0o755); err != nil {
144			return nil, err
145		}
146		s := &Store{
147			dir:     dir,
148			file:    filepath.Join(dir, "water-data.json"),
149			points:  map[string]SamplingPoint{},
150			limits:  map[limitGroup][]Limit{},
151			samples: map[string]*Sample{},
152		}
153		data, err := os.ReadFile(s.file)
154		if errors.Is(err, fs.ErrNotExist) {
155			return s, nil
156		}
157		if err != nil {
158			return nil, err
159		}
160		var st diskState
161		if err := json.Unmarshal(data, &st); err != nil {
162			return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
163		}
164		if st.Points != nil {
165			s.points = st.Points
166		}
167		if st.Limits != nil {
168			// 不按落盘键分组：键可能是旧版本用单字符拼接生成的，包含 U+0000 的
169			// 不同（采样点，项目）组合会共用同一个键。以每条限值自身的两个字段为准，
170			// 让曾经被错误合并的组在重新打开时也能各自归位。
171			for _, versions := range st.Limits {
172				for _, lim := range versions {
173					g := limitGroup{pointID: lim.PointID, item: lim.Item}
174					s.limits[g] = append(s.limits[g], lim)
175				}
176			}
177			for g, versions := range s.limits {
178				sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
179				s.limits[g] = versions
180			}
181		}
182		if st.Samples != nil {
183			// 逐份校验后才整体接收：任何状态的样品都必须至少保留一个原测量，
184			// 原测量项目名重复也都是损坏，带结论的样品还要求逐项判定与原测量
185			// 完整对应。任一份样品不通过，整次打开都失败，不返回数据存放对象，
186			// 也不静默跳过、择一保留、补测量、补判定或回写原文件。
187			ids := make([]string, 0, len(st.Samples))
188			for id := range st.Samples {
189				ids = append(ids, id)
190			}
191			sort.Strings(ids)
192			for _, id := range ids {
193				if err := validateLoadedSample(id, st.Samples[id]); err != nil {
194					return nil, err
195				}
196			}
197			s.samples = st.Samples
198		}
199		return s, nil
200	}
201	
202	// validateLoadedSample 校验一份从本地文件读入的样品记录。
203	//
204	// 无论样品处于什么状态，都必须至少保留一个原测量项目：Measurements 为空列表、
205	// 保存为 null 或整个字段在文件中缺失，都表示样品内容残缺，即使编号、采样点、
206	// 采样时间齐全也不能接受。待判定样品与待判定后作废（Results 为空、没有历史
207	// 判定依据）的样品同样适用，不能因为它们不再参与有效判定就放过内容丢失；
208	// 原测量为空但残留逐项判定的记录也不能反过来用判定内容填补原测量。
209	//
210	// 原测量项目名也不允许重复：同一个项目名在 Measurements 中只能出现一次，按
211	// 文件中保存的完整项目名判断，不依赖两条记录是否相邻，也不因数值相同（含两个
212	// 零）而放行。待判定样品与待判定后作废的样品虽然没有逐项结果，仍要过这一关；
213	// 它们没有判定记录本身不是损坏，测量项目不重复即正常读入，不会被要求已经有
214	// 判定依据。
215	//
216	// 带结论的样品还要满足：已确认样品，以及已确认后作废、Results 中仍保留历史依据
217	// 的样品，其原测量项目与逐项判定必须按项目名一一对应；判定中同一项目不能出现
218	// 两次；每个测量项目必须且只能有一条判定记录，判定中也不能出现原测量没有的
219	// 项目；对应项目的判定测量值必须与原测量值逐位一致（零是合法测量值，按 map
220	// 中是否存在该项目判断，不把零当成缺项）。项目按名称对应，与两个列表的排列
221	// 顺序无关。key 是落盘 map 中的样品编号，用于在记录本身残缺（如空记录）时
222	// 仍能指出是哪份样品。
223	func validateLoadedSample(key string, smp *Sample) error {
224		if smp == nil {
225			return fmt.Errorf("%w: 样品 %s 的记录为空", ErrCorruptRecord, key)
226		}
227		id := smp.ID
228		if id == "" {
229			id = key
230		}
231		// 至少一个原测量项目是任何状态样品（含待判定、待判定后作废）的读入前提：
232		// 空列表、null 或字段缺失都算内容残缺，必须在打开时整次拒绝，不能等请求
233		// 确认时才暴露，也不能用残留的逐项判定反填原测量。
234		if len(smp.Measurements) == 0 {
235			return fmt.Errorf("%w: 样品 %s 缺少原测量：原测量项目列表为空、为 null 或字段缺失",
236				ErrCorruptRecord, id)
237		}
238		// 原测量项目名去重适用于任何状态的样品（含待判定、待判定后作废）：
239		// 重复测量是记录本身损坏，不能等确认保存判定依据时才暴露。
240		meas := make(map[string]float64, len(smp.Measurements))
241		for _, m := range smp.Measurements {
242			if _, ok := meas[m.Item]; ok {
243				return fmt.Errorf("%w: 样品 %s 的测量项目 %s 重复", ErrCorruptRecord, id, m.Item)
244			}
245			meas[m.Item] = m.Value
246		}
247		// 待判定样品与待判定后作废（没有历史依据）的样品没有逐项判定，
248		// 原测量不重复即为正常记录，不要求它们已经有结论。
249		if smp.Status != StatusConfirmed && len(smp.Results) == 0 {
250			return nil
251		}
252		got := make(map[string]float64, len(smp.Results))
253		for _, r := range smp.Results {
254			if _, ok := got[r.Item]; ok {
255				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定记录重复", ErrCorruptRecord, id, r.Item)
256			}
257			got[r.Item] = r.Value
258		}
259		// 缺项或判定测量值与原测量不一致（按测量列表顺序报告，保持信息稳定）。
260		for _, m := range smp.Measurements {
261			rv, ok := got[m.Item]
262			if !ok {
263				return fmt.Errorf("%w: 样品 %s 缺少项目 %s 的判定记录", ErrCorruptRecord, id, m.Item)
264			}
265			if rv != m.Value {
266				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定测量值 %g 与原测量值 %g 不一致",
267					ErrCorruptRecord, id, m.Item, rv, m.Value)
268			}
269		}
270		// 判定中出现原测量没有的项目。
271		for _, r := range smp.Results {
272			if _, ok := meas[r.Item]; !ok {
273				return fmt.Errorf("%w: 样品 %s 的判定记录出现了原测量中没有的项目 %s",
274					ErrCorruptRecord, id, r.Item)
275			}
276		}
277		return nil
278	}
279	
280	// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
281	func (s *Store) Close() error {
282		s.mu.Lock()
283		defer s.mu.Unlock()
284		if s.closed {
285			return nil
286		}
287		s.closed = true
288		return nil
289	}
290	
291	func clean(s string) string { return strings.TrimSpace(s) }
292	
293	// diskLimitKey 生成仅用于落盘 JSON 的分组键。带上两个字段的长度前缀，
294	// 任何包含 U+0000 的文本组合都不会撞键；读取时并不依赖该键分组。
295	func diskLimitKey(pointID, item string) string {
296		return strconv.Itoa(len(pointID)) + ":" + pointID + strconv.Itoa(len(item)) + ":" + item
297	}
298	
299	func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
300	
301	// invalidUTF8 报告文本是否无法作为合法 UTF-8 原样保存。必须在任何处理之前检查
302	// 提交的原始文本：落盘 JSON 会把非法字节（孤立的 0xFF、0xFE、不完整的多字节
303	// 序列等）静默替换成 U+FFFD，返回记录与保存内容会因此对不上，两个不同编号也
304	// 可能变成同一文本。真正的 U+FFFD（“�”）以及中文、U+0000 等都是合法字符，
305	// 不在拒绝之列；只在去首尾空白之外不做任何字符替换或归一化。
306	func invalidUTF8(s string) bool { return !utf8.ValidString(s) }
307	
308	func (s *Store) checkOpenLocked() error {
309		if s.closed {
310			return ErrClosed
311		}
312		return nil
313	}
314	
315	// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
316	// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
317	func (s *Store) persistLocked() error {
318		diskLimits := make(map[string][]Limit, len(s.limits))
319		for g, versions := range s.limits {
320			diskLimits[diskLimitKey(g.pointID, g.item)] = versions
321		}
322		data, err := json.MarshalIndent(diskState{
323			Points:  s.points,
324			Limits:  diskLimits,
325			Samples: s.samples,
326		}, "", "  ")
327		if err != nil {
328			return err
329		}
330		tmp := s.file + ".tmp"
331		if err := os.WriteFile(tmp, data, 0o644); err != nil {
332			return err
333		}
334		return os.Rename(tmp, s.file)
335	}
336	
337	// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
338	// 保存和比较均使用处理后的文本；重复编号拒绝。
339	// 编号和名称必须都是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE 字节
340	// 或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
341	// 拒绝，不占用编号、不改动任何已有采样点；即使另一项为空白，或编号已登记而
342	// 这次名称含非法字节，也报告编码错误。真正的 U+FFFD（“�”）、中文和文本内部
343	// 的 U+0000 仍是合法字符。
344	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
345		s.mu.Lock()
346		defer s.mu.Unlock()
347		if err := s.checkOpenLocked(); err != nil {
348			return SamplingPoint{}, err
349		}
350		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
351		// 静默替换成 U+FFFD，登记“成功”后保存的编号或名称就会与填写内容对不上，
352		// 两个不同编号（如末尾分别带孤立 0xFF、0xFE）还可能保存成同一编号；
353		// 只有整次拒绝才能保证采样点身份在保存前后一致。
354		if invalidUTF8(id) || invalidUTF8(name) {
355			return SamplingPoint{}, ErrInvalidText
356		}
357		id, name = clean(id), clean(name)
358		if id == "" || name == "" {
359			return SamplingPoint{}, ErrEmptyField
360		}
361		if _, ok := s.points[id]; ok {
362			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
363		}
364		p := SamplingPoint{ID: id, Name: name}
365		s.points[id] = p
366		if err := s.persistLocked(); err != nil {
367			delete(s.points, id)
368			return SamplingPoint{}, err
369		}
370		return p, nil
371	}
372	
373	// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
374	// 采样点编号和项目名必须是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE
375	// 字节或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
376	// 拒绝，不新增版本、不占用生效时间；真正的 U+FFFD（“�”）、中文和文本内部的
377	// U+0000 仍是合法字符。即使同次请求还存在采样点未登记、数值不是有限数或
378	// 生效时间缺失的问题，也报告文本编码错误。
379	// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
380	func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
381		s.mu.Lock()
382		defer s.mu.Unlock()
383		if err := s.checkOpenLocked(); err != nil {
384			return Limit{}, err
385		}
386		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
387		// 静默替换成 U+FFFD，登记“成功”后保存的项目名就会与填写内容对不上，
388		// 限值也不再属于实际填写的采样点和项目；只有整次拒绝才能保证一致。
389		if invalidUTF8(pointID) || invalidUTF8(item) {
390			return Limit{}, ErrInvalidText
391		}
392		pointID, item = clean(pointID), clean(item)
393		if pointID == "" || item == "" {
394			return Limit{}, ErrEmptyField
395		}
396		if _, ok := s.points[pointID]; !ok {
397			return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
398		}
399		if !finite(value) {
400			return Limit{}, ErrInvalidValue
401		}
402		if effective.IsZero() {
403			return Limit{}, ErrInvalidTime
404		}
405		lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
406		g := limitGroup{pointID: pointID, item: item}
407		versions := s.limits[g]
408		for _, v := range versions {
409			if v.Effective.Equal(lim.Effective) {
410				return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
411			}
412		}
413		old := s.limits[g]
414		// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
415		// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
416		versions = make([]Limit, len(old)+1)
417		copy(versions, old)
418		versions[len(old)] = lim
419		sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
420		s.limits[g] = versions
421		if err := s.persistLocked(); err != nil {
422			s.limits[g] = old
423			return Limit{}, err
424		}
425		return lim, nil
426	}
427	
428	// SubmitSample 录入一份样品，初始为待判定状态。
429	// 样品编号、采样点编号和每个项目名必须是合法的 UTF-8 文本：任一字段含孤立的
430	// 0xFF、0xFE 字节或不完整的多字节序列等无法原样保存的内容时，整份提交以
431	// ErrInvalidText 拒绝，不留部分记录，也不占用编号；真正的 U+FFFD（“�”）
432	// 仍是合法字符。再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
433	// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
434	func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
435		s.mu.Lock()
436		defer s.mu.Unlock()
437		if err := s.checkOpenLocked(); err != nil {
438			return Sample{}, err
439		}
440		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
441		// 静默替换成 U+FFFD，只有整份拒绝才能保证返回记录、按点查看与保存数据一致。
442		// 即使编号已被已有样品占用、非法项目排在最后，或提交同时存在其它内容问题，
443		// 也必须报告编码问题：不能归为未知采样点、项目重复或同编号冲突，更不能走
444		// 重复录入成功的分支。
445		if invalidUTF8(id) || invalidUTF8(pointID) {
446			return Sample{}, ErrInvalidText
447		}
448		for _, m := range measurements {
449			if invalidUTF8(m.Item) {
450				return Sample{}, ErrInvalidText
451			}
452		}
453		id, pointID = clean(id), clean(pointID)
454		if id == "" || pointID == "" {
455			return Sample{}, ErrEmptyField
456		}
457		if sampledAt.IsZero() {
458			return Sample{}, ErrInvalidTime
459		}
460		if len(measurements) == 0 {
461			return Sample{}, ErrNoMeasurements
462		}
463		ms := make([]Measurement, len(measurements))
464		seen := make(map[string]float64, len(measurements))
465		for i, m := range measurements {
466			item := clean(m.Item)
467			if item == "" {
468				return Sample{}, ErrEmptyField
469			}
470			if !finite(m.Value) {
471				return Sample{}, ErrInvalidValue
472			}
473			if _, dup := seen[item]; dup {
474				return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
475			}
476			seen[item] = m.Value
477			ms[i] = Measurement{Item: item, Value: m.Value}
478		}
479		sampledAt = sampledAt.UTC()
480	
481		if existing, ok := s.samples[id]; ok {
482			if sameSampleContent(existing, pointID, sampledAt, seen) {
483				return copySample(existing), nil
484			}
485			return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
486		}
487		if _, ok := s.points[pointID]; !ok {
488			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
489		}
490		smp := &Sample{
491			ID:           id,
492			PointID:      pointID,
493			SampledAt:    sampledAt,
494			Measurements: ms,
495			Status:       StatusPending,
496		}
497		s.samples[id] = smp
498		if err := s.persistLocked(); err != nil {
499			delete(s.samples, id)
500			return Sample{}, err
501		}
502		return copySample(smp), nil
503	}
504	
505	func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
506		if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
507			return false
508		}
509		for _, m := range s.Measurements {
510			v, ok := ms[m.Item]
511			if !ok || v != m.Value {
512				return false
513			}
514		}
515		return true
516	}
517	
518	// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
519	// 测量值大于上限才超标，任一项目超标则整份样品超标。
520	// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
521	// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
522	func (s *Store) Confirm(id string) (Sample, error) {
523		s.mu.Lock()
524		defer s.mu.Unlock()
525		if err := s.checkOpenLocked(); err != nil {
526			return Sample{}, err
527		}
528		id = clean(id)
529		if id == "" {
530			return Sample{}, ErrEmptyField
531		}
532		smp, ok := s.samples[id]
533		if !ok {
534			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
535		}
536		switch smp.Status {
537		case StatusVoided:
538			return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
539		case StatusConfirmed:
540			return copySample(smp), nil
541		}
542	
543		results := make([]ItemResult, 0, len(smp.Measurements))
544		exceeded := false
545		for _, m := range smp.Measurements {
546			lim, ok := applicableLimit(s.limits[limitGroup{pointID: smp.PointID, item: m.Item}], smp.SampledAt)
547			if !ok {
548				return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
549			}
550			ex := m.Value > lim.Value
551			if ex {
552				exceeded = true
553			}
554			results = append(results, ItemResult{
555				Item:           m.Item,
556				Value:          m.Value,
557				Limit:          lim.Value,
558				LimitEffective: lim.Effective,
559				Exceeded:       ex,
560			})
561		}
562		smp.Results = results
563		smp.Exceeded = exceeded
564		smp.Status = StatusConfirmed
565		if err := s.persistLocked(); err != nil {
566			smp.Results = nil
567			smp.Exceeded = false
568			smp.Status = StatusPending
569			return Sample{}, err
570		}
571		return copySample(smp), nil
572	}
573	
574	// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
575	// 采样时间恰好等于生效时间时使用该版新值。
576	func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
577		best := -1
578		for i, v := range versions {
579			if v.Effective.After(at) {
580				break
581			}
582			best = i
583		}
584		if best < 0 {
585			return Limit{}, false
586		}
587		return versions[best], true
588	}
589	
590	// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
591	// 作废原因必须是合法的 UTF-8 文本：原始原因含孤立的 0xFF、0xFE 字节或不完整
592	// 的多字节序列等无法原样保存的内容时，本次作废整体以 ErrInvalidText 拒绝，
593	// 返回空样品，不删除或替换任何字节、不改动样品状态与已有原因；即使样品编号
594	// 不存在，或样品已作废而这次原因与原原因不同，也报告文本编码错误，而不是
595	// 样品不存在或原因冲突（数据存放已关闭时仍返回 ErrClosed）。真正的 U+FFFD
596	// （“�”）、中文、表情和文本内部的 U+0000 仍是合法字符。作废后保留测量、原因
597	// 和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
598	func (s *Store) Void(id, reason string) (Sample, error) {
599		s.mu.Lock()
600		defer s.mu.Unlock()
601		if err := s.checkOpenLocked(); err != nil {
602			return Sample{}, err
603		}
604		// 在去首尾空白、查找样品和比对原因等任何处理之前检查原始原因：落盘 JSON
605		// 会把非法 UTF-8 静默替换成 U+FFFD，作废“成功”后当场返回的原因仍带原始
606		// 字节，保存与重开后却变成替换字符，同一记录前后对不上，再次提交原原因
607		// 还会被误判成原因冲突；只有整次拒绝才能保证原因在保存前后一致。
608		if invalidUTF8(reason) {
609			return Sample{}, ErrInvalidText
610		}
611		id, reason = clean(id), clean(reason)
612		if id == "" || reason == "" {
613			return Sample{}, ErrEmptyField
614		}
615		smp, ok := s.samples[id]
616		if !ok {
617			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
618		}
619		if smp.Status == StatusVoided {
620			if smp.VoidReason == reason {
621				return copySample(smp), nil
622			}
623			return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
624		}
625		oldStatus := smp.Status
626		smp.Status = StatusVoided
627		smp.VoidReason = reason
628		if err := s.persistLocked(); err != nil {
629			smp.Status = oldStatus
630			smp.VoidReason = ""
631			return Sample{}, err
632		}
633		return copySample(smp), nil
634	}
635	
636	// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
637	func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
638		s.mu.Lock()
639		defer s.mu.Unlock()
640		if err := s.checkOpenLocked(); err != nil {
641			return nil, err
642		}
643		return s.pointSamplesLocked(clean(pointID), func(*Sample) bool { return true }), nil
644	}
645	
646	// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
647	// 没有已确认且未作废的样品时 ok 为 false。
648	func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
649		s.mu.Lock()
650		defer s.mu.Unlock()
651		if err := s.checkOpenLocked(); err != nil {
652			return Sample{}, false, err
653		}
654		list := s.pointSamplesLocked(clean(pointID), func(smp *Sample) bool {
655			return smp.Status == StatusConfirmed
656		})
657		if len(list) == 0 {
658			return Sample{}, false, nil
659		}
660		return list[0], true, nil
661	}
662	
663	// pointSamplesLocked 收集某采样点符合 keep 的样品，逐份复制后按统一规则排列，
664	// 供 ListByPoint 与 LatestResult 共用，保证两种查询对同一批样品的先后判断一致。
665	// 调用方须已持有锁；pointID 须已做首尾空白处理。
666	func (s *Store) pointSamplesLocked(pointID string, keep func(*Sample) bool) []Sample {
667		var list []Sample
668		for _, smp := range s.samples {
669			if smp.PointID == pointID && keep(smp) {
670				list = append(list, copySample(smp))
671			}
672		}
673		sortSamples(list)
674		return list
675	}
676	
677	func sortSamples(list []Sample) {
678		sort.Slice(list, func(i, j int) bool {
679			a, b := list[i], list[j]
680			if !a.SampledAt.Equal(b.SampledAt) {
681				return a.SampledAt.After(b.SampledAt)
682			}
683			return a.ID < b.ID
684		})
685	}
686	
687	func copySample(s *Sample) Sample {
688		c := *s
689		c.Measurements = append([]Measurement(nil), s.Measurements...)
690		c.Results = append([]ItemResult(nil), s.Results...)
691		return c
692	}
693

