6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 本文件保护“打开本地数据”时的记录完整性校验：
14	// 每份样品的原测量中同一个项目名只能出现一次，这条规则对任何状态的样品都生效，
15	// 包括没有逐项判定的待判定样品，以及待判定后直接作废、没有历史判定依据的样品；
16	// 重复按保存的完整项目名判断，不靠相邻、不因同值（含两个零）放行。
17	// 带结论的样品还要求原测量项目与逐项判定按项目名完整一一对应、且对应项目的
18	// 测量值一致；缺项、多项、判定项目重复、测量值对不上（零也是合法测量值）或
19	// 整份样品没有测量项目，都必须让整次 Open 失败，返回 nil 存放，错误信息点到
20	// 具体样品编号与项目，且不覆盖原文件、不静默跳过、不择一保留或合并重复测量、
21	// 不补判定、不改成待判定。待判定样品、待判定后作废（无历史依据）的样品在原测量
22	// 不重复时不受影响；已确认后作废但历史依据完整的样品继续兼容。
23	
24	const (
25		openPH   = "pH"
26		openTurb = "浊度"
27	)
28	
29	func openEff() time.Time { return at(1, 0) }
30	
31	// writeDiskFile 手工写入一份数据文件，便于构造正常流程不会产生的损坏记录。
32	func writeDiskFile(t *testing.T, dir string, st diskState) {
33		t.Helper()
34		data, err := json.MarshalIndent(st, "", "  ")
35		if err != nil {
36			t.Fatalf("marshal data file: %v", err)
37		}
38		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
39			t.Fatalf("write data file: %v", err)
40		}
41	}
42	
43	func openPoints() map[string]SamplingPoint {
44		return map[string]SamplingPoint{"P1": {ID: "P1", Name: "一号取水口"}}
45	}
46	
47	// phTurbResults 是与 pH 9、浊度 4 的原测量完整对应的两条判定，
48	// 排列顺序故意与测量相反，用来证明按项目名对应而非按位置对应。
49	func phTurbResults() []ItemResult {
50		return []ItemResult{
51			{Item: openTurb, Value: 4, Limit: 4, LimitEffective: openEff(), Exceeded: false},
52			{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
53		}
54	}
55	
56	func phTurbMeasurements() []Measurement {
57		return []Measurement{
58			{Item: openPH, Value: 9},
59			{Item: openTurb, Value: 4},
60		}
61	}
62	
63	// assertOpenRejects 断言打开整次失败：返回 nil 存放、错误可识别为
64	// ErrCorruptRecord，且信息包含出问题的样品编号与项目（noItem 为 true 时
65	// 只要求编号），原文件字节不被改动。
66	func assertOpenRejects(t *testing.T, dir, sampleID, itemHint string, noItem bool) {
67		t.Helper()
68		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
69		if err != nil {
70			t.Fatalf("read file before open: %v", err)
71		}
72		got, err := Open(dir)
73		if err == nil {
74			if got != nil {
75				got.Close()
76			}
77			t.Fatalf("损坏数据必须让整次 Open 失败，sample=%s", sampleID)
78		}
79		if got != nil {
80			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
81		}
82		if !errors.Is(err, ErrCorruptRecord) {
83			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
84		}
85		msg := err.Error()
86		if !strings.Contains(msg, sampleID) {
87			t.Fatalf("错误信息应指出样品编号 %q，实际 %q", sampleID, msg)
88		}
89		if !noItem && itemHint != "" && !strings.Contains(msg, itemHint) {
90			t.Fatalf("错误信息应指出项目 %q，实际 %q", itemHint, msg)
91		}
92		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
93		if rerr != nil {
94			t.Fatalf("read file after open: %v", rerr)
95		}
96		if string(after) != string(before) {
97			t.Fatalf("打开失败不得覆盖或改写原数据文件")
98		}
99	}
100	
101	// 已确认样品只剩一个项目的判定依据（浊度缺失）：即使整份超标标记还在，
102	// 也不能凭该标记返回达标或超标，整次打开失败并点名样品与缺失项目。
103	func TestOpenConfirmedMissingItemResult(t *testing.T) {
104		dir := t.TempDir()
105		writeDiskFile(t, dir, diskState{
106			Points: openPoints(),
107			Samples: map[string]*Sample{
108				"S1": {
109					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
110					Measurements: phTurbMeasurements(),
111					Status:       StatusConfirmed, Exceeded: true,
112					Results: []ItemResult{
113						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
114					},
115				},
116			},
117		})
118		assertOpenRejects(t, dir, "S1", openTurb, false)
119	}
120	
121	// 两条判定都在，但浊度判定里的测量值写成了 3（原测量是 4）：
122	// 项目名称相同也不能接受来自另一份记录的测量值，整次打开失败。
123	func TestOpenConfirmedMismatchedValue(t *testing.T) {
124		dir := t.TempDir()
125		results := phTurbResults()
126		results[0].Value = 3 // 浊度 4 被写成 3
127		writeDiskFile(t, dir, diskState{
128			Points: openPoints(),
129			Samples: map[string]*Sample{
130				"S1": {
131					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
132					Measurements: phTurbMeasurements(),
133					Status:       StatusConfirmed, Exceeded: false,
134					Results: results,
135				},
136			},
137		})
138		assertOpenRejects(t, dir, "S1", openTurb, false)
139	}
140	
141	// 零是合法测量值：原测量与判定都是零时必须正常读入；只有判定值被改成
142	// 非零（对不上）时才拒绝，不能把零当成没有填写。
143	func TestOpenConfirmedZeroValueIsValid(t *testing.T) {
144		dir := t.TempDir()
145		zeroResults := []ItemResult{
146			{Item: openTurb, Value: 0, Limit: 4, LimitEffective: openEff(), Exceeded: false},
147			{Item: openPH, Value: 0, Limit: 8, LimitEffective: openEff(), Exceeded: false},
148		}
149	
150		// 完整且为零：成功读入，零值原样保留。
151		writeDiskFile(t, dir, diskState{
152			Points: openPoints(),
153			Samples: map[string]*Sample{
154				"S1": {
155					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
156					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
157					Status:       StatusConfirmed, Exceeded: false,
158					Results: zeroResults,
159				},
160			},
161		})
162		s, err := Open(dir)
163		if err != nil {
164			t.Fatalf("零是合法测量值，完整记录应正常读入: %v", err)
165		}
166		list, err := s.ListByPoint("P1")
167		if err != nil || len(list) != 1 {
168			t.Fatalf("ListByPoint: %+v err=%v", list, err)
169		}
170		ms := map[string]float64{}
171		for _, m := range list[0].Measurements {
172			ms[m.Item] = m.Value
173		}
174		if ms[openPH] != 0 || ms[openTurb] != 0 {
175			t.Fatalf("零测量值必须原样保留: %+v", list[0].Measurements)
176		}
177		if err := s.Close(); err != nil {
178			t.Fatalf("Close: %v", err)
179		}
180	
181		// 判定把零改成 1：对不上，整次失败；错误仍点名该项目。
182		bad := []ItemResult{
183			zeroResults[0],
184			{Item: openPH, Value: 1, Limit: 8, LimitEffective: openEff(), Exceeded: false},
185		}
186		writeDiskFile(t, dir, diskState{
187			Points: openPoints(),
188			Samples: map[string]*Sample{
189				"S1": {
190					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
191					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
192					Status:       StatusConfirmed, Exceeded: false,
193					Results: bad,
194				},
195			},
196		})
197		assertOpenRejects(t, dir, "S1", openPH, false)
198	}
199	
200	// 同一项目在原测量里出现两次，是记录有误：整次打开失败。
201	func TestOpenConfirmedDuplicateMeasurement(t *testing.T) {
202		dir := t.TempDir()
203		writeDiskFile(t, dir, diskState{
204			Points: openPoints(),
205			Samples: map[string]*Sample{
206				"S1": {
207					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
208					Measurements: []Measurement{
209						{Item: openPH, Value: 9}, {Item: openPH, Value: 7},
210					},
211					Status: StatusConfirmed, Exceeded: true,
212					Results: []ItemResult{
213						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
214					},
215				},
216			},
217		})
218		assertOpenRejects(t, dir, "S1", openPH, false)
219	}
220	
221	// 同一项目在判定中出现两次，同样是记录有误：整次打开失败。
222	func TestOpenConfirmedDuplicateResult(t *testing.T) {
223		dir := t.TempDir()
224		writeDiskFile(t, dir, diskState{
225			Points: openPoints(),
226			Samples: map[string]*Sample{
227				"S1": {
228					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
229					Measurements: []Measurement{{Item: openPH, Value: 9}},
230					Status:       StatusConfirmed, Exceeded: true,
231					Results: []ItemResult{
232						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
233						{Item: openPH, Value: 9, Limit: 6, LimitEffective: openEff(), Exceeded: true},
234					},
235				},
236			},
237		})
238		assertOpenRejects(t, dir, "S1", openPH, false)
239	}
240	
241	// 判定中出现原测量没有的项目：整次打开失败并点名多出的项目。
242	func TestOpenConfirmedExtraResultItem(t *testing.T) {
243		dir := t.TempDir()
244		writeDiskFile(t, dir, diskState{
245			Points: openPoints(),
246			Samples: map[string]*Sample{
247				"S1": {
248					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
249					Measurements: []Measurement{{Item: openPH, Value: 9}},
250					Status:       StatusConfirmed, Exceeded: true,
251					Results: []ItemResult{
252						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
253						{Item: "COD", Value: 1, Limit: 30, LimitEffective: openEff(), Exceeded: false},
254					},
255				},
256			},
257		})
258		assertOpenRejects(t, dir, "S1", "COD", false)
259	}
260	
261	// 已确认样品一个测量项目都没有时也要失败，错误指出是哪份样品。
262	func TestOpenConfirmedNoMeasurements(t *testing.T) {
263		dir := t.TempDir()
264		writeDiskFile(t, dir, diskState{
265			Points: openPoints(),
266			Samples: map[string]*Sample{
267				"S1": {
268					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
269					Status: StatusConfirmed, Exceeded: false,
270					Results: nil,
271				},
272			},
273		})
274		assertOpenRejects(t, dir, "S1", "", true)
275	}
276	
277	// 一个文件里其他样品正常，也不能静默跳过有问题的样品继续打开：
278	// 整次失败、无可用存放，正常样品也读不到。
279	func TestOpenOneBadSampleRejectsWholeFile(t *testing.T) {
280		dir := t.TempDir()
281		writeDiskFile(t, dir, diskState{
282			Points: openPoints(),
283			Samples: map[string]*Sample{
284				// 完整、正常的已确认样品。
285				"S-GOOD": {
286					ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
287					Measurements: []Measurement{{Item: openPH, Value: 7}},
288					Status:       StatusConfirmed, Exceeded: false,
289					Results: []ItemResult{
290						{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
291					},
292				},
293				// 缺浊度判定的损坏样品。
294				"S-BAD": {
295					ID: "S-BAD", PointID: "P1", SampledAt: at(10, 0),
296					Measurements: phTurbMeasurements(),
297					Status:       StatusConfirmed, Exceeded: true,
298					Results: []ItemResult{
299						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
300					},
301				},
302			},
303		})
304		assertOpenRejects(t, dir, "S-BAD", openTurb, false)
305	}
306	
307	// 完整记录按项目名对应：两个列表排列顺序不同不影响读入；读入后测量与判定
308	// 仍各自保留原有顺序，已保存的上限、生效时间、逐项结论与整份超标标记原样保留。
309	func TestOpenCompleteRecordOrderPreserved(t *testing.T) {
310		dir := t.TempDir()
311		wantMeas := phTurbMeasurements() // pH 在前、浊度在后
312		wantResults := phTurbResults()   // 浊度在前、pH 在后（故意相反）
313		writeDiskFile(t, dir, diskState{
314			Points: openPoints(),
315			Samples: map[string]*Sample{
316				"S1": {
317					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
318					Measurements: wantMeas,
319					Status:       StatusConfirmed, Exceeded: true,
320					Results: wantResults,
321				},
322			},
323		})
324		s, err := Open(dir)
325		if err != nil {
326			t.Fatalf("完整记录（顺序相反）应正常读入: %v", err)
327		}
328		defer s.Close()
329	
330		latest, ok, err := s.LatestResult("P1")
331		if err != nil || !ok || latest.ID != "S1" {
332			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
333		}
334		// 原测量顺序保留。
335		if len(latest.Measurements) != 2 ||
336			latest.Measurements[0].Item != openPH || latest.Measurements[0].Value != 9 ||
337			latest.Measurements[1].Item != openTurb || latest.Measurements[1].Value != 4 {
338			t.Fatalf("原测量顺序必须保留: %+v", latest.Measurements)
339		}
340		// 判定顺序保留。
341		if len(latest.Results) != 2 ||
342			latest.Results[0].Item != openTurb || latest.Results[0].Value != 4 ||
343			latest.Results[1].Item != openPH || latest.Results[1].Value != 9 {
344			t.Fatalf("逐项判定顺序必须保留: %+v", latest.Results)
345		}
346		// 已保存的上限、生效时间、逐项结论与整份超标标记原样保留，不重新计算。
347		turb := latest.Results[0]
348		if turb.Limit != 4 || !turb.LimitEffective.Equal(openEff()) || turb.Exceeded {
349			t.Fatalf("浊度判定依据应原样保留: %+v", turb)
350		}
351		ph := latest.Results[1]
352		if ph.Limit != 8 || !ph.LimitEffective.Equal(openEff()) || !ph.Exceeded {
353			t.Fatalf("pH 判定依据应原样保留: %+v", ph)
354		}
355		if !latest.Exceeded {
356			t.Fatalf("整份超标标记应原样保留为 true")
357		}
358		// 重复确认返回同一份已保存依据。
359		again, err := s.Confirm("S1")
360		if err != nil {
361			t.Fatalf("重复确认: %v", err)
362		}
363		if len(again.Results) != 2 || again.Results[0].Item != openTurb ||
364			again.Results[1].Item != openPH || !again.Exceeded {
365			t.Fatalf("重复确认应返回原保存依据: %+v", again.Results)
366		}
367	}
368	
369	// 后来新增或补录的限值即使会改变重新判定的结果，也不能据此拒绝完整记录，
370	// 更不能在打开时重算结论：已保存的上限、生效时间与超标结论保持原样。
371	func TestOpenCompleteRecordUnaffectedByNewerLimits(t *testing.T) {
372		s, dir := open(t)
373		mustPoint(t, s, "P1", "一号取水口")
374		mustLimit(t, s, "P1", openPH, 8.0, openEff())
375		mustSample(t, s, "S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 9})
376		conf, err := s.Confirm("S1")
377		if err != nil || !conf.Exceeded || conf.Results[0].Limit != 8.0 {
378			t.Fatalf("setup: 9 > 8 应超标: %+v err=%v", conf, err)
379		}
380		if err := s.Close(); err != nil {
381			t.Fatalf("Close: %v", err)
382		}
383	
384		// 补录一版采样时刻之后才生效、更宽松的限值；再补一版采样之前生效的
385		// 宽松限值（若重算就会变成达标）。
386		s2, err := Open(dir)
387		if err != nil {
388			t.Fatalf("reopen for backfill: %v", err)
389		}
390		mustLimit(t, s2, "P1", openPH, 100.0, at(15, 0))
391		mustLimit(t, s2, "P1", openPH, 100.0, at(2, 0))
392		if err := s2.Close(); err != nil {
393			t.Fatalf("Close s2: %v", err)
394		}
395	
396		// 重新打开：完整记录不被新限值拒绝，结论仍是保存时的 8@09-01、超标。
397		s3, err := Open(dir)
398		if err != nil {
399			t.Fatalf("含新增限值时重新打开完整记录不应失败: %v", err)
400		}
401		defer s3.Close()
402		latest, ok, err := s3.LatestResult("P1")
403		if err != nil || !ok {
404			t.Fatalf("最近有效结果: %+v ok=%v err=%v", latest, ok, err)
405		}
406		if !latest.Exceeded || len(latest.Results) != 1 {
407			t.Fatalf("整份结论被重算: %+v", latest)
408		}
409		r := latest.Results[0]
410		if r.Value != 9 || r.Limit != 8.0 || !r.LimitEffective.Equal(openEff()) || !r.Exceeded {
411			t.Fatalf("已保存依据必须原样保留，不能按新限值重算: %+v", r)
412		}
413	}
