859		dir := t.TempDir()
860		s, err := Open(dir)
861		if err != nil {
862			t.Fatalf("全新数据目录应正常打开: %v", err)
863		}
864		if list, err := s.ListByPoint("P1"); err != nil || len(list) != 0 {
865			t.Fatalf("全新目录应没有样品: %+v err=%v", list, err)
866		}
867		if err := s.Close(); err != nil {
868			t.Fatalf("Close: %v", err)
869		}
870	
