func TestLimitGroupReloadOldCollidedFile(t *testing.T) {
	dir := t.TempDir()
	zeroPoint := "P\x00A"
	zeroItem := "A\x00B"
	eff := at(1, 0)

	// 手工构造旧格式文件：两组限值落在同一个碰撞键下，
	// 但每条记录各自带着正确的 pointId/item。
	oldKey := zeroPoint + "\x00" + "B" // 旧算法的键，与 "P" + "\x00" + zeroItem 相同
	if oldKey != "P"+"\x00"+zeroItem {
		t.Fatal("test setup: 两个组合应拼出同一个旧键")
	}
	old := diskState{
		Points: map[string]SamplingPoint{
			zeroPoint: {ID: zeroPoint, Name: "带零编号"},
			"P":       {ID: "P", Name: "普通编号"},
		},
		Limits: map[string][]Limit{
			oldKey: {
				{PointID: zeroPoint, Item: "B", Value: 10, Effective: eff},
				{PointID: "P", Item: zeroItem, Value: 5, Effective: eff},
			},
		},
		Samples: map[string]*Sample{
			"SN": {
				ID: "SN", PointID: "P", SampledAt: at(2, 0),
				Measurements: []Measurement{{Item: zeroItem, Value: 7}},
				Status:       StatusConfirmed, Exceeded: true,
				Results: []ItemResult{{
					Item: zeroItem, Value: 7, Limit: 5,
					LimitEffective: eff, Exceeded: true,
				}},
			},
		},
	}
	data, err := json.MarshalIndent(old, "", "  ")
	if err != nil {
		t.Fatalf("marshal old file: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
		t.Fatalf("write old file: %v", err)
	}

	s, err := Open(dir)
	if err != nil {
		t.Fatalf("Open old file: %v", err)
	}
	defer s.Close()

	if got := s.limits[limitGroup{pointID: zeroPoint, item: "B"}]; len(got) != 1 || got[0].Value != 10 {
		t.Fatalf("旧文件重新分组失败（zeroPoint 组）: %+v", got)
	}
	if got := s.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 1 || got[0].Value != 5 {
		t.Fatalf("旧文件重新分组失败（P 组）: %+v", got)
	}

	// 已确认样品保留原结论与所用限值，不自动重新判定
	kept, err := s.Confirm("SN")
	if err != nil {
		t.Fatalf("Confirm kept sample: %v", err)
	}
	if r := kept.Results[0]; !kept.Exceeded || r.Item != zeroItem ||
		r.Value != 7 || r.Limit != 5 || !r.LimitEffective.Equal(eff) {
		t.Fatalf("已确认样品结论被改动: %+v", kept)
	}

	// 同一时刻两组各自再登记仍互不冲突；同组重复仍拒绝
	if _, err := s.SetLimit(zeroPoint, "B", 11, at(5, 0)); err != nil {
		t.Fatalf("两组独立补录应成功: %v", err)
	}

package water

import (
	"bytes"
	"errors"
	"math"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// 本文件的测试只针对一件事：录入只接受能作为合法 UTF-8 原样保存的文本。
// 样品编号、采样点编号或任一项目名含孤立 0xFF、0xFE 字节或不完整的多字节
// 序列时，整份提交必须返回空样品和可被 errors.Is(err, water.ErrInvalidText)
// 识别的专用文本编码错误：不留下部分记录（哪怕非法项目排在最后）、不占用
// 样品编号、不改变按点查看与最近有效结果，也不能被归为未知采样点、项目重复、
// 同编号冲突或走重复录入成功分支。真正的 U+FFFD（“�”）、中文、其它有效
// 多字节字符以及内部 U+0000 仍然接受；文本处理只去首尾空白。

// notEncodingError 之外的这些错误都不允许冒充编码问题。
func assertEncodingError(t *testing.T, err error, label string) {
	t.Helper()
	if !errors.Is(err, ErrInvalidText) {
		t.Fatalf("%s: 应返回 ErrInvalidText，实际为 %v", label, err)
	}
	for _, target := range []error{
		ErrEmptyField, ErrUnknownPoint, ErrInvalidValue, ErrInvalidTime,
		ErrNoMeasurements, ErrDuplicateItem, ErrSampleConflict,
	} {
		if errors.Is(err, target) {
			t.Fatalf("%s: 编码问题不能被归为 %v: %v", label, target, err)
		}
	}
}

func assertNoReplacementBytes(t *testing.T, dir, label string) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
	if err != nil {
		t.Fatalf("%s: 读取落盘文件: %v", label, err)
	}
	if bytes.Contains(data, []byte{0xEF, 0xBF, 0xBD}) {
		t.Fatalf("%s: 被拒绝的非法文本被替换成 U+FFFD 落盘", label)
	}
}

// 非法文本出现在编号、采样点编号或任一项目名（含排在最后的项目）时整份拒绝，
// 不留下部分记录；即使提交同时还带着未知采样点、项目重复、非有限数值、
// 零采样时间等其它问题，也必须报告编码问题。
func TestSubmitSampleRejectsInvalidUTF8(t *testing.T) {
	s, dir := open(t)
	mustPoint(t, s, "P1", "取水口")
	mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
	mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))

	bad := []string{
		"S\xff",           // 孤立 0xFF
		"S\xfe",           // 孤立 0xFE
		"S\xe4\xb8",       // 不完整的三字节序列
		"S\xc0\xaf",       // 非法多字节序列
		"pH" + "\xff",     // 项目名末尾的孤立 0xFF
		"浊度" + "\xfe",     // 合法中文后接孤立 0xFE
		"\xe4\xb8" + "pH", // 项目名开头不完整序列
	}

	submit := func(label, id, point string, at time.Time, ms ...Measurement) {
		t.Helper()
		got, err := s.SubmitSample(id, point, at, ms...)
		assertEncodingError(t, err, label)
		if got.ID != "" || got.PointID != "" || got.Status != "" || len(got.Measurements) != 0 {
			t.Fatalf("%s: 失败必须返回空样品，实际为 %+v", label, got)
		}
	}

	// 编号非法
	submit("编号含 0xFF", bad[0], "P1", at(10, 0), Measurement{Item: "pH", Value: 7})
	submit("编号含 0xFE", bad[1], "P1", at(10, 0), Measurement{Item: "pH", Value: 7})
	submit("编号含不完整序列", bad[2], "P1", at(10, 0), Measurement{Item: "pH", Value: 7})

